const $=id=>document.getElementById(id);
let currentSession=null;
const labels={chat:"Conversations",models:"Models & providers",memory:"Memory",usage:"Usage & analytics",settings:"Settings"};
async function api(url,opts={}){const r=await fetch(url,{...opts,headers:{"Content-Type":"application/json",...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||"Request failed");return d}
function showLogin(){ $("login").classList.remove("hidden");$("app").classList.add("hidden")}
function showApp(){ $("login").classList.add("hidden");$("app").classList.remove("hidden")}
async function checkAuth(){try{await api("/api/status");showApp();await loadSessions()}catch{showLogin()}}
$("login-form").addEventListener("submit",async e=>{e.preventDefault();$("login-error").textContent="";try{await api("/api/login",{method:"POST",body:JSON.stringify({username:$("username").value,password:$("password").value})});showApp();await loadSessions()}catch(err){$("login-error").textContent=err.message}});
$("logout").onclick=async()=>{try{await api("/api/logout",{method:"POST"})}finally{showLogin()}};
async function loadSessions(){const list=await api("/api/sessions");$("session-list").innerHTML="";list.forEach(s=>{const b=document.createElement("button");b.className="session-item"+(s.id===currentSession?" active":"");b.textContent=s.title;b.onclick=()=>openSession(s.id);$("session-list").appendChild(b)});if(!currentSession&&list.length)openSession(list[0].id)}
async function newSession(){const s=await api("/api/sessions",{method:"POST"});currentSession=s.id;await loadSessions();$("welcome").classList.add("hidden");$("conversation").classList.remove("hidden");$("messages").innerHTML="";$("message-input").focus()}
async function openSession(id){currentSession=id;const msgs=await api("/api/messages?session_id="+encodeURIComponent(id));$("welcome").classList.add("hidden");$("conversation").classList.remove("hidden");$("messages").innerHTML="";msgs.forEach(addMessage);await loadSessions();$("messages").scrollTop=$("messages").scrollHeight}
function addMessage(m){const row=document.createElement("div");row.className="message "+m.role;const av=document.createElement("div");av.className="msg-avatar";av.textContent=m.role==="user"?"S":"✳";const bubble=document.createElement("div");bubble.className="bubble";bubble.textContent=m.content;row.append(av,bubble);$("messages").appendChild(row)}
$("new-chat").onclick=$("start-chat").onclick=newSession;
$("chat-form").addEventListener("submit",async e=>{e.preventDefault();const input=$("message-input"),text=input.value.trim();if(!text)return;if(!currentSession)await newSession();input.value="";addMessage({role:"user",content:text});const wait={role:"assistant",content:"Thinking…"};addMessage(wait);const submit=e.submitter;$("chat-form").querySelector(".send").disabled=true;try{const result=await api("/api/messages",{method:"POST",body:JSON.stringify({session_id:currentSession,message:text,model:$("model").value})});$("messages").lastElementChild.remove();addMessage({role:"assistant",content:result.reply});}catch(err){$("messages").lastElementChild.remove();addMessage({role:"assistant",content:"Error: "+err.message})}finally{$("chat-form").querySelector(".send").disabled=false;await loadSessions();$("messages").scrollTop=$("messages").scrollHeight}});
document.querySelectorAll(".nav[data-view],.nav[data-view]").forEach(b=>b.addEventListener("click",()=>switchView(b.dataset.view)));
function switchView(view){document.querySelectorAll(".nav").forEach(b=>b.classList.toggle("active",b.dataset.view===view));["chat-view","placeholder-view","settings-view"].forEach(id=>$(id).classList.add("hidden"));$("page-name").textContent=labels[view]||"Workspace";if(view==="chat")$("chat-view").classList.remove("hidden");else if(view==="settings"){$("settings-view").classList.remove("hidden");api("/api/status").then(s=>$("gemini-state").textContent=s.gemini_configured?"CONNECTED":"NOT CONFIGURED").catch(()=>{});}else{$("placeholder-view").classList.remove("hidden");$("placeholder-title").textContent=labels[view];$("placeholder-copy").textContent="This module is reserved in the Sahand-Cortext architecture. Its interface will be activated in a future release."}}
$("message-input").addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();$("chat-form").requestSubmit()}});
checkAuth();
